<template><div class="transform-grid" data-testid="transform-inspector"><small v-if="locked">装配编辑模式下内部 Link 锁定</small><template v-for="(v,i) in draft.xyz" :key="`p${i}`"><label>{{['X','Y','Z'][i]}}<el-input-number v-model="draft.xyz[i]" :disabled="locked" :controls="false" :step="0.001" @change="save" /></label></template><template v-for="(v,i) in draft.rpy" :key="`r${i}`"><label>{{['R','P','Y'][i]}}<el-input-number v-model="draft.rpy[i]" :disabled="locked" :controls="false" :step="0.01" @change="save" /></label></template><template v-if="draft.scale"><label v-for="(_,i) in draft.scale" :key="`s${i}`">S{{['X','Y','Z'][i]}}<el-input-number v-model="draft.scale[i]" :min="0.0001" :controls="false" @change="save" /></label></template></div></template>
<script setup lang="ts">import {computed,reactive,watch} from 'vue';import {useEditorStore} from '@/stores/editor';import type {EditableTransform} from '@/api/transforms';const store=useEditorStore(),draft=reactive<EditableTransform>({xyz:[0,0,0],rpy:[0,0,0]}),locked=computed(()=>store.selectedType==='link'&&store.editSemantic==='assembly');function current():EditableTransform{if(store.selectedType==='model_instance')return store.scene.rootTransform;const j=store.selectedType==='joint'||store.selectedType==='assembly_connection'?store.scene.joints.find(x=>x.id===store.selectedId):store.selectedType==='link'?store.scene.joints.find(x=>x.child===store.selectedId):undefined;if(j)return j.origin;for(const l of store.scene.links){const v=l.visuals.find(x=>x.id===store.selectedId);if(v)return{...v.origin,scale:v.scale}}return{xyz:[0,0,0],rpy:[0,0,0]}}function sync(){const v=current();draft.xyz=[...v.xyz];draft.rpy=[...v.rpy];draft.scale=v.scale?[...v.scale]:undefined}async function save(){if(!locked.value&&store.selectedType&&store.selectedId)await store.commit(store.selectedType,store.selectedId,{xyz:[...draft.xyz],rpy:[...draft.rpy],scale:draft.scale&&[...draft.scale]})}watch(()=>[store.selectedType,store.selectedId,store.scene.revision],sync,{immediate:true})</script>
